-- State transitions declared for JobCard: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION manufacturing.job_cards_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('blocked', 'cancel'), ('blocked', 'done'), ('blocked', 'progress'), ('blocked', 'ready'), ('progress', 'cancel'), ('progress', 'done'), ('ready', 'blocked'), ('ready', 'cancel'), ('ready', 'done'), ('ready', 'progress'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: job_cards.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_job_cards__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS job_cards_status_transition_check ON manufacturing.job_cards;
CREATE TRIGGER job_cards_status_transition_check
    BEFORE UPDATE OF "status" ON manufacturing.job_cards
    FOR EACH ROW EXECUTE FUNCTION manufacturing.job_cards_status_transition_check();
